import{_ as e,o as a,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const s="/study/images/game/game-engine-basics.svg",u=JSON.parse('{"title":"ゲームエンジンの役割 — 素材とルールからゲームを動かす","description":"","frontmatter":{"title":"ゲームエンジンの役割 — 素材とルールからゲームを動かす","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"プレイヤーを表示して動かす場面から、ゲームエンジン、エディター、実行時の機能、アセット、プロジェクト、ビルドの役割を説明する。","aliases":["ゲームエンジン","game engine","Unity","Unreal Engine","エディター","editor","ランタイム","プロジェクト","アセット","ビルド","ゲームロジック"],"verification":"Unity 6.0のアセット・シーン・ビルドとEpicのGameplay Frameworkの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/game-engine-basics.md","filePath":"game/basics/game-engine-basics.md"}'),i={name:"game/basics/game-engine-basics.md"};function o(d,t,l,m,h,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="ゲームエンジンの役割-—-素材とルールからゲームを動かす" tabindex="-1">ゲームエンジンの役割 — 素材とルールからゲームを動かす <a class="header-anchor" href="#ゲームエンジンの役割-—-素材とルールからゲームを動かす" aria-label="Permalink to &quot;ゲームエンジンの役割 — 素材とルールからゲームを動かす&quot;">​</a></h1><p>プレイヤーを画面に表示し、入力で動かし、壁に当たったら止めるゲームを考えます。そこには画像を作る処理、機器からの入力、衝突の計算、ファイルの読み込みなどが必要です。<strong>ゲームエンジン</strong>は、こうしたゲームで使う機能や実行の仕組みを提供するソフトウェアです。UnityやUnreal Engineには、制作を支援するエディターもあります。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/get-started" target="_blank" rel="noreferrer">Unityの制作環境の概要</a> · <a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/gameplay-framework-in-unreal-engine" target="_blank" rel="noreferrer">Unreal EngineのGameplay Framework</a></p><h2 id="ゲームのルールと、使う機能" tabindex="-1">ゲームのルールと、使う機能 <a class="header-anchor" href="#ゲームのルールと、使う機能" aria-label="Permalink to &quot;ゲームのルールと、使う機能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作りたい動作</th><th>エンジンの機能を使う例</th><th>ゲーム側で決めること</th></tr></thead><tbody><tr><td>キーでプレイヤーを動かす</td><td>入力を受け取り、オブジェクトの位置を更新する。</td><td>移動速度、操作できる状態。</td></tr><tr><td>キャラクターを表示する</td><td>メッシュと材質を使って、カメラから画像を作る。</td><td>使うモデル、見た目、カメラの置き方。</td></tr><tr><td>壁に当たる</td><td>コライダーや物理の計算を使う。</td><td>止まる、跳ね返る、ダメージを受けるなどのルール。</td></tr><tr><td>HPを表示する</td><td>UIの文字やゲージを表示する。</td><td>何を表示し、いつ更新するか。</td></tr></tbody></table><p>このように、作品ごとのルールを実装する処理を<strong>ゲームロジック</strong>と呼びます。エンジンが提供する部品と、自分で書いたコードや設定を組み合わせて作ります。Unreal EngineのGameplay Frameworkのように、ルールやプレイヤーの状態を実装するための構成も用意されています。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/gameplay-framework-in-unreal-engine" target="_blank" rel="noreferrer">Unreal Engineのゲームプレイの構成</a> · <a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a></p><figure class="study-figure"><img src="'+s+'" alt="ゲーム側の素材とルールを、エンジンの入力・シーン・描画・物理などの機能と組み合わせる。実行時にはOSと機器の機能も使う。制作中のエディターでは素材や設定を編集する。" width="760" height="446" loading="lazy"><figcaption>役割を見分ける概念図です。提供される機能やまとめ方はエンジンによって異なります。<a href="/study/images/game/game-engine-basics.svg" target="_blank" rel="noopener noreferrer">ゲームエンジンの図を拡大</a></figcaption></figure><h2 id="エディターで作り、実行時の機能で動かす" tabindex="-1">エディターで作り、実行時の機能で動かす <a class="header-anchor" href="#エディターで作り、実行時の機能で動かす" aria-label="Permalink to &quot;エディターで作り、実行時の機能で動かす&quot;">​</a></h2><p><strong>エディター</strong>は、素材を取り込み、オブジェクトを配置し、値を設定して動きを確認する制作の道具です。<strong>ランタイム</strong>は、作ったゲームを動かす側の仕組みです。エンジンの機能、ゲームのコード、必要なデータを使って実行が進みます。制作画面から再生する場合も、対象プラットフォーム向けに作ったアプリを起動する場合もあります。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/unity-editor" target="_blank" rel="noreferrer">Unityのエディター</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/BuildSettings.html" target="_blank" rel="noreferrer">Unityのビルド</a></p><p>例えばUnityの<strong>Gameビュー</strong>ではカメラからの表示を確認し、<strong>Sceneビュー</strong>では制作中の配置を編集できます。制作時に見ている視点と、ゲームで使うカメラを確認すると、表示される内容を追えます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/GameView.html" target="_blank" rel="noreferrer">UnityのGameビュー</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/UsingTheSceneView.html" target="_blank" rel="noreferrer">Sceneビュー</a></p><h2 id="アセット、プロジェクト、実行中の状態" tabindex="-1">アセット、プロジェクト、実行中の状態 <a class="header-anchor" href="#アセット、プロジェクト、実行中の状態" aria-label="Permalink to &quot;アセット、プロジェクト、実行中の状態&quot;">​</a></h2><p><strong>アセット</strong>は、制作に使うモデル、画像、シーン、コードなどの素材やデータです。<strong>プロジェクト</strong>には、使うアセットや設定、コードなどをまとめます。エンジンは素材を取り込み、対象の実行環境で使うデータを準備します。この取り込みを<strong>インポート</strong>と呼びます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/AssetWorkflow.html" target="_blank" rel="noreferrer">Unityのアセット</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/ImportingAssets.html" target="_blank" rel="noreferrer">アセットのインポート</a></p><table tabindex="0"><thead><tr><th>何を見ているか</th><th>例</th></tr></thead><tbody><tr><td>保存した素材・設定</td><td>プレイヤーのモデル、最初の位置、最大HP。</td></tr><tr><td>実行中のオブジェクトや値</td><td>今の位置、現在のHP、発射された弾。</td></tr><tr><td>次の起動に残す情報</td><td>クリア済みステージ、所持アイテム、保存した進行状況。</td></tr></tbody></table><p>ゲームは素材や設定から実行中の状態を用意し、更新していきます。進行状況を次の起動にも引き継ぐには、必要な情報を保存する処理を設計します。素材のファイル、実行中に使うデータ、セーブするデータをそれぞれ確認すると、読み込みや保存のタイミングを考えられます。<a href="/study/game/asset-loading.html">アセットロードの状態と所有権</a> · <a href="/study/os/files-and-paths.html">ファイルとパス</a></p><h2 id="小さな制作の流れ" tabindex="-1">小さな制作の流れ <a class="header-anchor" href="#小さな制作の流れ" aria-label="Permalink to &quot;小さな制作の流れ&quot;">​</a></h2><ol><li>モデルや画像を取り込み、必要な材質を用意する。</li><li>シーンにプレイヤー、カメラ、床などを配置する。</li><li>入力から移動へつなぐコードや設定を加える。</li><li>必要なら衝突判定やUIを組み合わせ、動作を確かめる。</li><li>対象プラットフォーム向けにビルドし、そのアプリでも動作を確認する。</li></ol><p><strong>ビルド</strong>では、コードやアセットを、選んだ環境で実行できるアプリにまとめます。エディターからの再生と、実機へ配布するアプリでは設定や使える機能が変わる場合があります。対象の設定をそろえて確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/BuildSettings.html" target="_blank" rel="noreferrer">Unityのビルド手順</a> · <a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルド</a></p><p>実行中に処理がどう回るかは<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a>、形と位置は<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a>と<a href="/study/graphics/basics/transforms-and-cameras.html">座標とカメラ</a>へ進めます。小さな作品にまとめる例は<a href="/study/game/shooter-design.html">シューティングの設計</a>で扱います。</p>',17)])])}const p=e(i,[["render",o]]);export{u as __pageData,p as default};
